import { Component, h, State } from "@stencil/core";

@Component({
  tag: "app-cards",
  shadow: true,
})
export class AppCards {
  @State() label = "app-cards: click to load helper";

  private async activate() {
    const mod = await import("../../helpers/helper-cards");
    this.label = mod.answer();
  }

  render() {
    return <button onClick={() => void this.activate()}>{this.label}</button>;
  }
}