import { Component, h, State } from "@stencil/core";

@Component({
  tag: "app-forms",
  shadow: true,
})
export class AppForms {
  @State() label = "app-forms: click to load helper";

  private async activate() {
    const mod = await import("../../helpers/helper-forms");
    this.label = mod.answer();
  }

  render() {
    return <button onClick={() => void this.activate()}>{this.label}</button>;
  }
}